-- Lote 09: traduções PT-BR de talentos SRD (6 registros).
update public.srd_feats as f
set nome_pt = v.nome_pt,
    descricao_pt = v.descricao_pt
from (values
('srd35_feat_enlarge_spell','Ampliar Magia','Benefício: Você pode alterar uma magia com alcance curto, médio ou longo para aumentar seu alcance em 100%. Uma magia ampliada de alcance curto passa a ter alcance de 50 pés + 5 pés por nível; uma magia de alcance médio passa a ter alcance de 200 pés + 20 pés por nível; e uma magia de alcance longo passa a ter alcance de 800 pés + 80 pés por nível. Uma magia ampliada ocupa um espaço de magia um nível acima do nível real da magia.\n\nMagias cujo alcance não é definido por distância, assim como magias cujo alcance não é curto, médio ou longo, não têm seu alcance aumentado.'),
('srd35_feat_eschew_materials','Dispensar Materiais','Benefício: Você pode conjurar qualquer magia que tenha um componente material com custo de 1 PO ou menos sem precisar desse componente. A conjuração ainda provoca ataques de oportunidade normalmente. Se a magia exigir um componente material que custe mais de 1 PO, você deverá tê-lo em mãos para conjurá-la, como de costume.'),
('srd35_feat_exotic_weapon_proficiency','Usar Arma Exótica','Escolha um tipo de arma exótica. Você aprende a usar esse tipo de arma em combate.\n\nPré-requisito: Bônus Base de Ataque +1 (além de Força 13 para espada bastarda ou machado de guerra anão).\n\nBenefício: Você realiza jogadas de ataque normalmente com a arma escolhida.\n\nNormal: Um personagem que usa uma arma com a qual não é proficiente sofre penalidade de –4 nas jogadas de ataque.\n\nEspecial: Você pode escolher Usar Arma Exótica várias vezes. Cada vez, o talento se aplica a um novo tipo de arma exótica. A proficiência com espada bastarda ou machado de guerra anão tem o pré-requisito adicional de Força 13.\n\nUm guerreiro pode escolher Usar Arma Exótica como um de seus talentos adicionais de guerreiro.'),
('srd35_feat_extend_spell','Estender Magia','Benefício: Uma magia estendida dura o dobro do tempo normal. Este talento não afeta magias com duração de concentração, instantânea ou permanente. Uma magia estendida ocupa um espaço de magia um nível acima do nível real da magia.'),
('srd35_feat_extra_turning','Expulsão Adicional','Pré-requisito: Capacidade de expulsar ou fascinar criaturas.\n\nBenefício: Cada vez que você escolhe este talento, pode usar sua capacidade de expulsar ou fascinar criaturas quatro vezes adicionais por dia.\n\nSe você tiver a capacidade de expulsar ou fascinar mais de um tipo de criatura, cada uma dessas capacidades recebe quatro usos adicionais por dia.\n\nNormal: Sem este talento, um personagem normalmente pode expulsar ou fascinar mortos-vivos (ou outras criaturas) um número de vezes por dia igual a 3 + seu modificador de Carisma.\n\nEspecial: Você pode escolher Expulsão Adicional várias vezes. Seus efeitos se acumulam. Cada vez que escolher este talento, cada uma de suas capacidades de expulsar ou fascinar recebe quatro usos adicionais por dia.'),
('srd35_feat_far_shot','Tiro Longo','Pré-requisito: Tiro Certeiro.\n\nBenefício: Quando você usa uma arma de projéteis, como um arco, seu incremento de distância aumenta em metade (multiplique por 1,5). Quando usa uma arma de arremesso, seu incremento de distância dobra.\n\nEspecial: Um guerreiro pode escolher Tiro Longo como um de seus talentos adicionais de guerreiro.')
) as v(id,nome_pt,descricao_pt)
where f.id = v.id;
